import logo from './logo.svg';
import './App.css';

function App() {
  return (
    <DashboardProvider>
      <div className="page">
        <Header />
        <main className="grid">
          <BudgetWidget />
          <SeatingWidget />
          <GuestListWidget />
          <VenuesWidget />
          <StaffingWidget />
        </main>
      </div>
    </DashboardProvider>
  )
}

export default App;
